lemmas.statement:
local lemma enc_oracle_eq :
    equiv[ PTXT_Wrap(MEE(PseudoRP,MAC)).enc ~ CMAa(PseudoRP,A,WUF_Wrap(MAC)).O.enc :
             ={arg}
          /\ PTXT_Wrap.k{1} = (CMAa.ek{2},WUF_Wrap.k{2})
          /\ PTXT_Wrap.s{1} = WUF_Wrap.s{2}
          /\ (PTXT_Wrap.win{1} => WUF_Wrap.win{2})
           ==>
             ={res}
          /\ PTXT_Wrap.k{1} = (CMAa.ek{2},WUF_Wrap.k{2})
          /\ PTXT_Wrap.s{1} = WUF_Wrap.s{2}
          /\ (PTXT_Wrap.win{1} => WUF_Wrap.win{2}) ].

local lemma verify_oracle_eq :
    equiv[ PTXT_Wrap(MEE(PseudoRP,MAC)).verify ~ CMAa(PseudoRP,A,WUF_Wrap(MAC)).O.verify :
             ={arg}
          /\ PTXT_Wrap.k{1} = (CMAa.ek{2},WUF_Wrap.k{2})
          /\ PTXT_Wrap.s{1} = WUF_Wrap.s{2}
          /\ (PTXT_Wrap.win{1} => WUF_Wrap.win{2})
           ==>
             ={res}
          /\ PTXT_Wrap.k{1} = (CMAa.ek{2},WUF_Wrap.k{2})
          /\ PTXT_Wrap.s{1} = WUF_Wrap.s{2}
          /\ (PTXT_Wrap.win{1} => WUF_Wrap.win{2}) ].

local lemma enc_real_bridge:
  equiv [ RCPA_Wrap(PadThenEncrypt(S)).enc ~ CoreDefs.RCPA.RCPA_Wrap(S).enc :
            ={glob S}
            /\ p{2} = pad p{1}
            /\ RCPA_Wrap.k{1} = CoreDefs.RCPA.RCPA_Wrap.k{2}
          ==> ={res, glob S}
            /\ RCPA_Wrap.k{1} = CoreDefs.RCPA.RCPA_Wrap.k{2} ].

